after:
{
  "active_scene_id": "ch1_scene01",
  "chapters": {
    "1": {
      "title": "世界一·乱世守护",
      "scenes": [
        {
          "id": "ch1_scene01",
          "title": "穿入立人设",
          "beat": "【场景目的】穿入 → 摸清身份和家庭 → 露一手小爽点（对应第1-2章）\n【人物动作】苏晚穿入后先摸环境、身份、处境；家庭氛围一笔带出，群像初现。\n【情绪目标】好奇/警觉\n【节奏档位】快\n【结尾钩子】第1章末：战乱的消息从远处传来，像闷雷。",
          "pace": "快",
          "summary": "第1-2章",
          "done": true,
          "updated_at": "2026-06-06T22:44:04",
          "emotion_anchor": {}
        },
        {
          "id": "ch1_scene02",
          "title": "初见男主",
          "beat": "【场景目的】城里遇见江砚，随手帮小忙（第3-4章）\n【人物动作】打短工/问路/卖东西场合相遇；她觉得他憨但眼里有东西。读者OS：姐你帮的是皇帝。\n【情绪目标】爽/好奇\n【节奏档位】中\n【结尾钩子】第4章末：家门口多了几匹陌生人的马。",
          "pace": "中",
          "summary": "第3-4章",
          "done": false,
          "updated_at": "2026-06-06T22:00:00"
        },
        {
          "id": "ch1_scene03",
          "title": "家庭日常与暗中布局",
          "beat": "【场景目的】群像展开，女主为乱世铺路（第5-7章）\n【人物动作】姐姐稳重、弟弟机灵、小妹亮点；囤东西/打听消息/藏退路；有人觉得她小题大做，有人被点醒。\n【情绪目标】温馨中带不安\n【节奏档位】中\n【结尾钩子】第7章末：城门口开始设卡了。",
          "pace": "中",
          "summary": "第5-7章",
          "done": false,
          "updated_at": "2026-06-06T22:00:00"
        },
        {
          "id": "ch1_scene04",
          "title": "山雨欲来",
          "beat": "【场景目的】紧张感升级，暗线启动（第8-10章）\n【人物动作】布局派上用场又遇新问题；和男主二次交集再帮一把；某家人第一次觉醒。\n【情绪目标】燃/揪心\n【节奏档位】快\n【结尾钩子】第10章末：乱军距城不到三日。",
          "pace": "快",
          "summary": "第8-10章",
          "done": false,
          "updated_at": "2026-06-06T22:00:00"
        },
        {
          "id": "ch1_scene05",
          "title": "战乱爆发·守护",
          "beat": "【场景目的】想护护不动的无力感 → 爆发（第11-14章）\n【人物动作】家人团结合力，女主押注男主；危急时他稳住局面，她只觉得关键时候靠得住。\n【情绪目标】爽/燃\n【节奏档位】快\n【结尾钩子】第14章末：新皇登基，改朝换代的消息在路上。",
          "pace": "快",
          "summary": "第11-14章",
          "done": false,
          "updated_at": "2026-06-06T22:00:00"
        },
        {
          "id": "ch1_scene06",
          "title": "结算·觉醒·回响",
          "beat": "【场景目的】明线暗线完成，漏妈妈线索，旧世界回响（第15章）\n【人物动作】家人活下来；觉醒的家人做最后一件事；结算漏线索；离开前看他站在城门下，她手指微微蜷了一下。\n【情绪目标】释然/咯噔\n【节奏档位】慢\n【结尾钩子】进入下一个世界。",
          "pace": "慢",
          "summary": "第15章",
          "done": false,
          "updated_at": "2026-06-06T22:00:00"
        }
      ]
    }
  }
}

